static void switches_pop(struct em_switches *members)
{
	struct neocc_switch *sw = members->state.current;

	members->state.current = sw->prev;
	for (int i = 0; i < sw->n; i++)
		free(sw->p[i]);
	free(sw->p);
	free(sw);
}

static void switches_clear(struct em_switches *members)
{
	while (members->state.current)
		switches_pop(members);
}

static int switches_open(struct object *self, const struct vr *caller_context)
{
	OBS_OBJECT_OPEN_;
	return R_P;
}

static int switches_close(struct object *self,
	const struct vr *caller_context)
{
	OBS_OBJECT_CLOSE_;
	if (!self->ref_count)
		switches_clear(self->members);
	return R_P;
}

static int switches_interact0(struct object *self, unsigned int action,
	const struct vr *caller_context)
{
	if (action != NEOCC_AC0_SWITCHES_RESET) {
		SBO_OBJECT_INTERACT0;
	}
	if (!self->ref_count)
		return RN_INVALIDARG;
	switches_clear(self->members);
	return R_P;
}

static int switches_interact1(struct object *self, unsigned int action,
	unsigned char *output_stream, unsigned int capacity,
	unsigned int *output_quantity, const struct vr *caller_context)
{
	struct em_switches *members = self->members;
	struct neocc_switch *sw = members->state.current;
	struct neocc_case *record;
	struct neocc_case **index;
	void *result;
	int count;

	*output_quantity = 0;
	if (action != NEOCC_AC1_SWITCHES_BORROW &&
	    action != NEOCC_AC1_SWITCHES_ENTER &&
	    action != NEOCC_AC1_SWITCHES_CASE) {
		SBO_OBJECT_INTERACT1;
	}
	if (!self->ref_count || capacity < sizeof(result))
		return RN_INVALIDARG;
	if (action == NEOCC_AC1_SWITCHES_BORROW) {
		result = &members->state;
	} else if (action == NEOCC_AC1_SWITCHES_ENTER) {
		sw = malloc(sizeof(*sw));
		if (!sw)
			return R_N;
		*sw = (struct neocc_switch){ 0 };
		sw->prev = members->state.current;
		members->state.current = sw;
		result = sw;
	} else {
		if (!sw || sw->n == INT_MAX)
			return RN_INVALIDARG;
		record = malloc(sizeof(*record));
		if (!record)
			return R_N;
		if (sw->n == sw->capacity) {
			count = sw->capacity > INT_MAX / 2 ? INT_MAX :
				sw->capacity ? sw->capacity * 2 : 1;
			if ((size_t)count > SIZE_MAX / sizeof(*index)) {
				free(record);
				return R_N;
			}
			index = realloc(sw->p, (size_t)count * sizeof(*index));
			if (!index) {
				free(record);
				return R_N;
			}
			sw->p = index;
			sw->capacity = count;
		}
		*record = (struct neocc_case){ 0 };
		sw->p[sw->n++] = record;
		result = record;
	}
	memcpy(output_stream, &result, sizeof(result));
	*output_quantity = sizeof(result);
	return R_P;
}

static int switches_interact2(struct object *self, unsigned int action,
	unsigned char *input_stream, unsigned int quantity,
	const struct vr *caller_context)
{
	struct em_switches *members = self->members;
	struct neocc_switch *sw = members->state.current, *request;
	int index;

	if (action != NEOCC_AC2_SWITCHES_EXIT &&
	    action != NEOCC_AC2_SWITCHES_REMOVE) {
		SBO_OBJECT_INTERACT2;
	}
	if (!self->ref_count || !sw)
		return RN_INVALIDARG;
	if (action == NEOCC_AC2_SWITCHES_EXIT) {
		if (quantity != sizeof(request))
			return RN_INVALIDARG;
		memcpy(&request, input_stream, sizeof(request));
		if (request != sw)
			return RN_INVALIDARG;
		switches_pop(members);
		return R_P;
	}
	if (quantity != sizeof(index))
		return RN_INVALIDARG;
	memcpy(&index, input_stream, sizeof(index));
	if (index < 0 || index >= sw->n)
		return RN_INVALIDARG;
	free(sw->p[index]);
	memmove(sw->p + index, sw->p + index + 1,
		(size_t)(--sw->n - index) * sizeof(*sw->p));
	return R_P;
}

