void tog_switches(struct object *object)
{
	object->open = switches_open;
	object->input = switches_input;
	object->output = switches_output;
	object->io_put = switches_io_put;
	object->interact0 = switches_interact0;
	object->interact1 = switches_interact1;
	object->interact2 = switches_interact2;
	object->interact3 = switches_interact3;
	object->close = switches_close;
}
